import React from 'react';
import './Menu.css';

const Menu = () => {
  const menuItems = [
    {
      id: 1,
      name: 'Kofta',
      price: 250,
      description: "Soft, spicy koftas soaking in rich, creamy gravy.",
      image: 'https://images.unsplash.com/photo-1603894584373-5ac82b2ae398',
      veg: true
    },
    // ... अन्य आइटम्स
  ];

  const handleOrderNow = (item) => {
    console.log("Ordering:", item.name);
    alert(`आपका ऑर्डर: ${item.name} हमारे स्टाफ को भेज दिया गया है!`);
  };

  return (
    <div className="menu-page">
      {/* ... अन्य कोड ... */}

      <div className="menu-items-container">
        {menuItems.map(item => (
          <div key={item.id} className="menu-item-card"> 
            <div className="food-image-container">
              <img src={item.image} alt={item.name} />
              <span className={`food-label ${item.veg ? 'vegetarian' : 'non-vegetarian'}`}>
                {item.veg ? 'शाकाहारी' : 'मांसाहारी'}
              </span>
            </div>
            <div className="food-details">
              <h3>{item.name}</h3>
              <p>{item.description}</p>
              <div className="price-order-container">
                <span>₹{item.price}</span>
                <button 
                  className="order-button"
                  onClick={() => handleOrderNow(item)}
                >
                  ऑर्डर करें
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Menu;
